{
  "group_id": {{GROUP_ID}},      // required | must exist and be one of YOUR groups (else 403)
  "student_id": 1,    // required | must exist and be in this group

  // "phase" — REQUIRED, 1 or 2: the phase the teacher is grading.
  // The degrees are saved in THIS phase. Today's date is NOT checked (any phase can be graded on any day).
  // Every element below must be for this phase or for both phases, else 422 and nothing is saved.
  "phase": 1,

  "degrees": [        // required | array | at least 1 item
    // evaluation_element_id: required | distinct (each element once) | exists | must be YOUR element of this group's SUBJECT | must be for the sent phase (or both phases)
    // degree: required | numeric (decimals allowed, e.g. 4.5) | >= 0 | <= the element's max_degree
    { "evaluation_element_id": 1, "degree": 80 },
    { "evaluation_element_id": 2, "degree": 65 },
    { "evaluation_element_id": 6, "degree": 40 }
  ]
}

